-- Economics Gen2 Season 2 Tour 2. Versioned hard and medium content, 6 easy/10 medium/4 hard.
-- Does not touch legacy Season 1 and aborts if there is learner history on the target season.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='75s';
DO $tour1$
DECLARE
 d jsonb:='[{"ref":"EC9708:G2:EC9708-G2-T2-T-007","d":"hard","sec":135,"k":"C","en":"Two households earn $18,000 and $82,000 before redistribution. The first receives a means-tested $7,000 transfer; the second pays an additional $13,000 tax. The poverty threshold is $28,000. By how much does the gap between their disposable incomes narrow, and does the poorer household cross the threshold?","ru":"До перераспределения два домохозяйства получают $18 000 и $82 000. Первое получает адресную выплату $7 000; второе платит дополнительный налог $13 000. Черта бедности — $28 000. На сколько сократится разрыв располагаемых доходов и выйдет ли беднейшая семья за черту бедности?","uz":"Qayta taqsimlashdan oldin ikki xonadon $18 000 va $82 000 oladi. Birinchisi $7 000 manzilli yordam oladi; ikkinchisi $13 000 qo‘shimcha soliq to‘laydi. Kambag‘allik chegarasi $28 000. Ixtiyordagi daromadlar farqi qanchaga qisqaradi va kam daromadli xonadon chegaradan chiqadimi?","options_en":["Gap narrows $13,000; yes, lower income becomes $31,000","Gap narrows $20,000; yes, lower income becomes $28,000","Gap narrows $20,000; no, lower income becomes $25,000","Gap widens $20,000; no, lower income remains $18,000"],"options_ru":["Разрыв сокращается на $13 000; да, доход становится $31 000","Разрыв сокращается на $20 000; да, доход достигает $28 000","Разрыв сокращается на $20 000; нет, доход становится $25 000","Разрыв растёт на $20 000; нет, доход остаётся $18 000"],"options_uz":["Farq $13 000 ga qisqaradi; ha, past daromad $31 000 bo‘ladi","Farq $20 000 ga qisqaradi; ha, daromad $28 000 bo‘ladi","Farq $20 000 ga qisqaradi; yo‘q, past daromad $25 000 bo‘ladi","Farq $20 000 ga oshadi; yo‘q, daromad $18 000 qoladi"],"why":["Before, the gap is $82,000−$18,000=$64,000. Afterwards incomes are $69,000 and $25,000, gap $44,000, a $20,000 narrowing. The poorer household is still below $28,000.","До мер разрыв $64 000. После мер доходы $69 000 и $25 000, разрыв $44 000. Он сокращается на $20 000, но $25 000 всё ещё ниже черты бедности $28 000.","Avval farq $64 000. Keyin daromadlar $69 000 va $25 000, farq $44 000. $20 000 ga qisqaradi, lekin $25 000 kambag‘allik chegarasidan past."]},{"ref":"EC9708:G2:EC9708-G2-T2-T-011","d":"hard","sec":135,"k":"B","en":"A government pays producers a $6 subsidy per unit. The market price paid by consumers falls from $20 to $17, while the equilibrium quantity rises from 1,000 to 1,200 units. What are the subsidy benefit per unit to producers and the total government expenditure at the new equilibrium?","ru":"Государство выдаёт производителям субсидию $6 на единицу товара. Цена для покупателей снижается с $20 до $17, равновесные продажи растут с 1 000 до 1 200 единиц. Сколько дополнительного дохода на единицу получают продавцы относительно прежней цены и каковы общие расходы бюджета на субсидию при новом равновесии?","uz":"Davlat ishlab chiqaruvchilarga har birlik uchun $6 subsidiya beradi. Xaridor narxi $20 dan $17 ga tushadi, muvozanat hajmi 1000 dan 1200 birlikka oshadi. Sotuvchi avvalgi narxga nisbatan har birlikda qancha qo‘shimcha oladi va yangi muvozanatda subsidiya bo‘yicha jami budjet xarajati qancha?","options_en":["Producer gain $6; expenditure $6,000","Producer gain $3; expenditure $7,200","Producer gain $3; expenditure $6,000","Producer gain $9; expenditure $7,200"],"options_ru":["Прирост у продавца $6; бюджет $6 000","Прирост у продавца $3; бюджет $7 200","Прирост у продавца $3; бюджет $6 000","Прирост у продавца $9; бюджет $7 200"],"options_uz":["Sotuvchi foydasi $6; budjet $6 000","Sotuvchi foydasi $3; budjet $7 200","Sotuvchi foydasi $3; budjet $6 000","Sotuvchi foydasi $9; budjet $7 200"],"why":["New producer receipt is consumer price $17 plus subsidy $6=$23; before it was $20, so producer gain is $3 per unit. Subsidy costs taxpayers $6×1,200=$7,200.","Новая выручка продавца за единицу $17+$6=$23 против прежних $20, прирост $3. Бюджет расходует $6×1 200=$7 200.","Sotuvchi yangi tushumi $17+$6=$23, avval $20 edi; foyda $3. Davlat xarajati $6×1200=$7200."]},{"ref":"EC9708:G2:EC9708-G2-T2-T-019","d":"hard","sec":135,"k":"D","en":"In a circular-flow model with households, government and foreign trade, planned saving is $45m, taxes $30m and imports $25m. Planned investment is $35m, government purchases $40m and exports $25m. Afterwards, government purchases rise by $9m while imports independently rise by $4m. What is the initial injection-leakage balance, and what is the direction of pressure on national income after the changes?","ru":"В модели кругооборота с государством и внешней торговлей планируемые сбережения $45 млн, налоги $30 млн, импорт $25 млн. Планируемые инвестиции $35 млн, госзакупки $40 млн, экспорт $25 млн. Затем госзакупки увеличиваются на $9 млн, а импорт независимо растёт на $4 млн. Каково исходное равенство инъекций и изъятий и каким будет давление на национальный доход после изменений?","uz":"Davlat va tashqi savdoli doiraviy oqim modelida rejalangan jamg‘arma $45 mln, soliq $30 mln, import $25 mln. Rejalangan investitsiya $35 mln, davlat xaridi $40 mln, eksport $25 mln. Keyin davlat xaridi $9 mln, import alohida $4 mln oshadi. Dastlab kirim va chiqimlar muvozanati qanday va o‘zgarishdan so‘ng milliy daromadga qanday bosim bo‘ladi?","options_en":["Initially leakages exceed injections by $25m; later income is under downward pressure","Initially injections exceed leakages by $5m; later income is under downward pressure","Initially injections equal leakages; later leakages exceed injections by $5m, pushing income down","Initially injections equal leakages at $100m; afterwards injections exceed leakages by $5m, pushing income up"],"options_ru":["Изначально изъятия превышают инъекции на $25 млн; затем доход снижается","Изначально инъекции превышают изъятия на $5 млн; затем доход снижается","Изначально равновесие; затем изъятия превышают инъекции на $5 млн, доход снижается","Изначально инъекции и изъятия равны $100 млн; затем инъекции выше изъятий на $5 млн, доход растёт"],"options_uz":["Dastlab chiqimlar kirimdan $25 mln ko‘p; keyin daromad pasayish bosimida","Dastlab kirimlar chiqimdan $5 mln ko‘p; keyin daromad pasayadi","Dastlab teng; keyin chiqim $5 mln ko‘proq bo‘lib daromad tushadi","Dastlab kirim va chiqim $100 mln ga teng; keyin kirim $5 mln yuqori bo‘lib daromad oshish bosimida"],"why":["Initially injections I+G+X=35+40+25=$100m, and leakages S+T+M=45+30+25=$100m. Later injections=$109m and leakages=$104m; the $5m planned injection surplus puts upward pressure on output and income.","Сначала инъекции 35+40+25=$100 млн и изъятия 45+30+25=$100 млн. Затем инъекции $109 млн, изъятия $104 млн: превышение инъекций на $5 млн создаёт повышательное давление на выпуск и доход.","Avval kirimlar 35+40+25=$100 mln, chiqimlar 45+30+25=$100 mln. Keyin kirim $109 mln, chiqim $104 mln: $5 mln ortiqcha kirim ishlab chiqarish va daromadni oshirishga bosim beradi."]},{"ref":"EC9708:G2:EC9708-G2-T2-T-020","d":"hard","sec":135,"k":"A","en":"An economy''s planned aggregate expenditure is C+I+G+(X−M). Initially C=$460bn, I=$90bn, G=$110bn, X=$70bn and M=$100bn. Later the government adds $15bn of purchases while household consumption falls by $8bn and imports rise by $5bn. Other items stay fixed. What are aggregate expenditure before and after these changes?","ru":"Планируемые совокупные расходы экономики рассчитываются как C+I+G+(X−M). Сначала C=$460 млрд, I=$90 млрд, G=$110 млрд, X=$70 млрд, M=$100 млрд. Затем госзакупки растут на $15 млрд, потребление сокращается на $8 млрд, импорт растёт на $5 млрд; остальные показатели неизменны. Каковы расходы до и после?","uz":"Yalpi rejalashtirilgan xarajat C+I+G+(X−M) shaklida. Dastlab C=$460 mlrd, I=$90 mlrd, G=$110 mlrd, X=$70 mlrd, M=$100 mlrd. Keyin davlat xaridi $15 mlrd oshadi, iste’mol $8 mlrd kamayadi, import $5 mlrd oshadi; boshqasi o‘zgarmaydi. O‘zgarishdan oldingi va keyingi jami xarajat qancha?","options_en":["$630bn before; $632bn after","$730bn before; $732bn after","$630bn before; $642bn after","$630bn before; $602bn after"],"options_ru":["До $630 млрд; после $632 млрд","До $730 млрд; после $732 млрд","До $630 млрд; после $642 млрд","До $630 млрд; после $602 млрд"],"options_uz":["Oldin $630 mlrd; keyin $632 mlrd","Oldin $730 mlrd; keyin $732 mlrd","Oldin $630 mlrd; keyin $642 mlrd","Oldin $630 mlrd; keyin $602 mlrd"],"why":["Initially AD=460+90+110+70−100=$630bn. Net change is −8+15−5=+$2bn; afterwards AD=$632bn. Imports are subtracted to avoid counting foreign production in domestic output expenditure.","Сначала совокупные расходы 460+90+110+70−100=$630 млрд. Изменение −8+15−5=+$2 млрд; новый показатель $632 млрд. Импорт вычитается.","Dastlab jami xarajat 460+90+110+70−100=$630 mlrd. Sof o‘zgarish −8+15−5=+$2 mlrd; keyin $632 mlrd. Import ayiriladi."]},{"ref":"EC9708:G2:EC9708-G2-T2-T-013","d":"medium","sec":115,"k":"B","en":"An economy''s gross domestic product is $720bn in Year A and $770bn in Year B. Depreciation of fixed capital is $40bn in A and $65bn in B. What are the two net domestic product figures, and by how much did net output rise?","ru":"Валовой внутренний продукт экономики равен $720 млрд в году A и $770 млрд в году B. Амортизация основного капитала составляет $40 млрд и $65 млрд соответственно. Найдите чистый внутренний продукт в обоих годах и прирост чистого выпуска.","uz":"Mamlakat yalpi ichki mahsuloti A yilida $720 mlrd va B yilida $770 mlrd. Asosiy kapital eskirishi mos ravishda $40 mlrd va $65 mlrd. Ikkala yildagi sof ichki mahsulot va sof mahsulot o‘sishi qancha?","options_en":["NDP $680bn and $705bn; net output rises $50bn","NDP $680bn and $705bn; net output rises $25bn","NDP $760bn and $835bn; net output rises $75bn","NDP $720bn and $770bn; net output rises $50bn"],"options_ru":["ЧВП $680 и $705 млрд; рост $50 млрд","ЧВП $680 и $705 млрд; рост $25 млрд","ЧВП $760 и $835 млрд; рост $75 млрд","ЧВП $720 и $770 млрд; рост $50 млрд"],"options_uz":["SIM $680 va $705 mlrd; o‘sish $50 mlrd","SIM $680 va $705 mlrd; o‘sish $25 mlrd","SIM $760 va $835 mlrd; o‘sish $75 mlrd","SIM $720 va $770 mlrd; o‘sish $50 mlrd"],"why":["NDP=GDP−capital depreciation. A=$720−$40=$680bn; B=$770−$65=$705bn. The net-output increase is $25bn, not the $50bn increase in GDP.","ЧВП=ВВП−амортизация. В году A $720−$40=$680 млрд, в B $770−$65=$705 млрд; прирост $25 млрд, меньше прироста ВВП $50 млрд.","SIM=YaIM−kapital eskirishi. A=$720−$40=$680 mlrd, B=$770−$65=$705 mlrd. Sof o‘sish $25 mlrd, YaIMdagi $50 mlrd emas."]},{"ref":"EC9708:G2:EC9708-G2-T2-T-014","d":"medium","sec":120,"k":"C","en":"At a competitive monthly rental rate of $600, 100 flats are demanded and supplied. A binding rent ceiling of $450 raises quantity demanded to 140 flats and reduces quantity supplied to 80. What is the shortage and how many of the original 100 flats are no longer supplied?","ru":"При равновесной месячной аренде $600 спрос и предложение составляют по 100 квартир. Обязательный потолок платы $450 увеличивает спрос до 140 квартир и уменьшает предложение до 80. Каков дефицит жилья и сколько квартир из первоначальных 100 теперь не предлагаются?","uz":"Muvozanatli oylik ijara $600 bo‘lganda talab ham, taklif ham 100 ta uy. Majburiy $450 narx chegarasi talabni 140 taga oshiradi, taklifni 80 taga kamaytiradi. Uy tanqisligi va avvalgi 100 ta taklifdan yo‘qolgan uy soni qancha?","options_en":["Shortage 40 flats; 60 initially supplied units disappear","Shortage 60 flats; 60 initially supplied units disappear","Shortage 60 flats; 20 initially supplied units disappear","Surplus 60 flats; 20 initially supplied units disappear"],"options_ru":["Дефицит 40 квартир; исчезает 60 прежних предложений","Дефицит 60 квартир; исчезает 60 прежних предложений","Дефицит 60 квартир; из прежнего предложения исчезает 20 квартир","Избыток 60 квартир; из предложения исчезает 20 квартир"],"options_uz":["Tanqislik 40 uy; avvalgi taklifdan 60 yo‘qoladi","Tanqislik 60 uy; avvalgi taklifdan 60 yo‘qoladi","Tanqislik 60 uy; avvalgi taklifdan 20 yo‘qoladi","Ortiqcha taklif 60 uy; avvalgi taklifdan 20 yo‘qoladi"],"why":["The shortage is Qd−Qs=140−80=60 flats. Supply falls from 100 to 80, a reduction of 20 flats; the two measurements are not the same.","Дефицит равен 140−80=60 квартир. Предложение уменьшается со 100 до 80, то есть на 20 квартир. Это разные показатели.","Tanqislik 140−80=60 uy. Taklif 100 dan 80 ga tushib 20 uy kamayadi. Ikkala ko‘rsatkich bir xil emas."]},{"ref":"EC9708:G2:EC9708-G2-T2-T-015","d":"medium","sec":120,"k":"D","en":"A city has a single water distributor. Its average cost is $3 per unit at output 1,000, and a regulator sets a price ceiling of $3.50. Before regulation, the firm charged $5 per unit and sold 1,000 units. Assuming costs and sales stay at those levels, how do revenue and accounting profit change?","ru":"В городе один поставщик воды. Его средние затраты составляют $3 за единицу при объёме 1 000. Регулятор вводит максимальную цену $3,50. Ранее фирма продавала 1 000 единиц по $5. Если объём и издержки остаются прежними, как меняются выручка и бухгалтерская прибыль?","uz":"Shaharda suvni bitta korxona yetkazadi. 1000 birlik hajmda o‘rtacha xarajat $3. Tartibga soluvchi eng yuqori narxni $3,50 deb belgilaydi. Ilgari firma 1000 birlikni $5 dan sotgan. Hajm va xarajat o‘zgarmasa, tushum va buxgalteriya foydasi qanday o‘zgaradi?","options_en":["Revenue falls $1,000; profit falls $500","Revenue falls $1,500; profit stays unchanged","Revenue stays $5,000; profit falls $1,500","Revenue falls $1,500; profit falls $1,500, remaining positive at $500"],"options_ru":["Выручка падает на $1 000; прибыль на $500","Выручка падает на $1 500; прибыль неизменна","Выручка остаётся $5 000; прибыль падает на $1 500","Выручка и прибыль падают на $1 500; прибыль остаётся положительной: $500"],"options_uz":["Tushum $1000, foyda $500 kamayadi","Tushum $1500 kamayadi, foyda o‘zgarmaydi","Tushum $5000 qoladi, foyda $1500 kamayadi","Tushum va foyda $1500 kamayadi; foyda $500 musbat qoladi"],"why":["Revenue falls from $5×1,000=$5,000 to $3.50×1,000=$3,500, down $1,500. Total cost stays $3,000, so profit moves from $2,000 to $500, also down $1,500.","Выручка снижается с $5 000 до $3 500, на $1 500. Затраты $3 000 неизменны; прибыль падает с $2 000 до $500, тоже на $1 500.","Tushum $5000 dan $3500 ga $1500 kamayadi. Jami xarajat $3000 qoladi; foyda $2000 dan $500 ga, $1500 kamayadi."]},{"ref":"EC9708:G2:EC9708-G2-T2-T-016","d":"medium","sec":115,"k":"A","en":"An economy reports gross value added at basic prices of $480bn. Taxes on products are $35bn and subsidies on products $12bn. In the next period subsidies increase by $8bn, while value added and taxes on products are unchanged. What is GDP at market prices before and after the subsidy rise?","ru":"Валовая добавленная стоимость экономики в основных ценах — $480 млрд. Налоги на продукты $35 млрд, субсидии на продукты $12 млрд. В следующем периоде субсидии увеличиваются на $8 млрд, добавленная стоимость и налоги неизменны. Чему равен ВВП в рыночных ценах до и после?","uz":"Asosiy narxlardagi yalpi qo‘shilgan qiymat $480 mlrd. Mahsulot soliqlari $35 mlrd, subsidiyalar $12 mlrd. Keyingi davrda subsidiya $8 mlrd oshadi, qo‘shilgan qiymat va soliq o‘zgarmaydi. Bozor narxidagi YaIM avval va keyin qancha?","options_en":["$503bn before; $495bn after","$527bn before; $535bn after","$480bn before; $472bn after","$503bn before; $511bn after"],"options_ru":["Сначала $503 млрд; затем $495 млрд","Сначала $527 млрд; затем $535 млрд","Сначала $480 млрд; затем $472 млрд","Сначала $503 млрд; затем $511 млрд"],"options_uz":["Avval $503 mlrd; keyin $495 mlrd","Avval $527 mlrd; keyin $535 mlrd","Avval $480 mlrd; keyin $472 mlrd","Avval $503 mlrd; keyin $511 mlrd"],"why":["GDP at market prices=GVA at basic prices+product taxes−product subsidies. Initially 480+35−12=$503bn; subsidies rise to 20, so GDP becomes 480+35−20=$495bn.","ВВП в рыночных ценах = добавленная стоимость в основных ценах + налоги на продукты − субсидии. Сначала 480+35−12=$503 млрд; затем 480+35−20=$495 млрд.","Bozor narxida YaIM=asosiy qo‘shilgan qiymat+mahsulot soliqlari−subsidiyalar. Avval 480+35−12=$503 mlrd; keyin 480+35−20=$495 mlrd."]},{"ref":"EC9708:G2:EC9708-G2-T2-T-018","d":"medium","sec":120,"k":"B","en":"Country A''s nominal GDP increases 15% while its GDP deflator increases 10%. Country B''s nominal GDP increases 8% while its deflator is unchanged. With no change in population, which country has faster growth of real GDP, using exact index ratios?","ru":"В стране A номинальный ВВП растёт на 15%, дефлятор ВВП — на 10%. В стране B номинальный ВВП растёт на 8%, дефлятор не меняется. Численность населения постоянна. В какой стране реальный ВВП растёт быстрее по точным отношениям индексов?","uz":"A mamlakatda nominal YaIM 15%, deflyator 10% oshadi. B mamlakatda nominal YaIM 8% oshadi, deflyator o‘zgarmaydi. Aholi soni o‘zgarmas. Indekslarning aniq nisbatiga ko‘ra qaysi mamlakatda real YaIM tezroq o‘sadi?","options_en":["A, because nominal GDP rises 15%","B: real growth is 8% versus about 4.55% in A","A: real growth is 25% versus 8% in B","Real growth is equal because prices and output cannot be separated"],"options_ru":["A, потому что номинальный ВВП растёт на 15%","B: реальный рост 8% против примерно 4,55% в A","A: реальный рост 25% против 8% в B","Реальный рост одинаков, поскольку цены невозможно отделить от выпуска"],"options_uz":["A, chunki nominal YaIM 15% oshadi","B: real o‘sish 8%, A da esa taxminan 4,55%","A: real o‘sish 25%, B da 8%","Real o‘sish teng, chunki narxni mahsulotdan ajratib bo‘lmaydi"],"why":["A real-growth factor is 1.15/1.10≈1.04545, a 4.55% gain. B has 1.08/1.00=1.08, or 8% real growth, despite lower nominal growth.","Для A индекс реального роста 1,15/1,10≈1,04545, то есть 4,55%. Для B — 1,08/1,00=1,08, или 8%. Реальный рост быстрее в B.","A ning real o‘sish koeffitsienti 1,15/1,10≈1,04545, 4,55%. B da 1,08/1,00=1,08, 8%. B tezroq o‘sadi."]}]'::jsonb;
 x jsonb; oldq record; new_id bigint; i int; idx int; keytxt text; reftext text; cnt int;
 enwhy text; ruwhy text; uzwhy text; ez int; med int; hard int;
BEGIN
 IF jsonb_array_length(d)<>9 THEN RAISE EXCEPTION 'T2_nine_replacements_required'; END IF;
 IF EXISTS(SELECT 1 FROM public.tour_attempts at JOIN public.tours t ON t.id=at.tour_id WHERE t.subject_id=7 AND t.season_id=2 AND t.tour_no=2)
 THEN RAISE EXCEPTION 'T2_season2_attempts_exist'; END IF;
 SELECT count(*) INTO cnt FROM public.tours t JOIN public.tour_questions l ON l.tour_id=t.id AND l.is_active
 WHERE t.subject_id=7 AND t.season_id=2 AND t.tour_no=2;
 IF cnt<>20 THEN RAISE EXCEPTION 'T2_pool_not20_before: %',cnt; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(d) LOOP
   reftext:=x->>'ref';keytxt:=x->>'k';idx:=ascii(keytxt)-65;
   IF keytxt NOT IN ('A','B','C','D') OR x->>'d' NOT IN ('hard','medium')
      OR jsonb_array_length(x->'options_en')<>4 OR jsonb_array_length(x->'options_ru')<>4
      OR jsonb_array_length(x->'options_uz')<>4
   THEN RAISE EXCEPTION 'T2_invalid_authoring: %',reftext; END IF;
   SELECT q.id,q.subject_id,q.topic,q.subtopic,q.quality_flag,l.tour_id,l.order_no
   INTO STRICT oldq FROM public.questions q JOIN public.tour_questions l ON l.question_id=q.id AND l.is_active
   JOIN public.tours t ON t.id=l.tour_id
   WHERE q.subject_id=7 AND t.subject_id=7 AND t.season_id=2 AND t.tour_no=2 AND q.book_ref=reftext;
   IF EXISTS(SELECT 1 FROM public.tour_answers a WHERE a.question_id=oldq.id)
      OR EXISTS(SELECT 1 FROM public.tour_session_answers_v4 a WHERE a.question_id=oldq.id)
      OR EXISTS(SELECT 1 FROM public.questions q WHERE q.subject_id=7 AND q.book_ref=reftext||'-V2')
   THEN RAISE EXCEPTION 'T2_history_or_duplicate: %',reftext; END IF;
   enwhy:=x->'why'->>0;ruwhy:=x->'why'->>1;uzwhy:=x->'why'->>2;
   INSERT INTO public.questions(subject_id,topic,subtopic,difficulty,qtype,question_text,options_text,correct_answer,explanation,image_url,is_active,
   question_text_ru,question_text_uz,question_text_en,options_text_ru,options_text_uz,options_text_en,explanation_ru,explanation_uz,explanation_en,book_ref,time_limit_sec,quality_flag,quality_status)
   VALUES(oldq.subject_id,oldq.topic,oldq.subtopic,x->>'d','mcq',x->>'en',(x->'options_en')::text,keytxt,
   'Correct: '||(x->'options_en'->>idx)||E'\n'||enwhy,NULL,true,
   x->>'ru',x->>'uz',x->>'en',(x->'options_ru')::text,(x->'options_uz')::text,(x->'options_en')::text,
   'Правильный ответ: '||(x->'options_ru'->>idx)||E'\n'||ruwhy,
   'To‘g‘ri javob: '||(x->'options_uz'->>idx)||E'\n'||uzwhy,
   'Correct answer: '||(x->'options_en'->>idx)||E'\n'||enwhy,
   reftext||'-V2',(x->>'sec')::int,oldq.quality_flag,'published')
   RETURNING id INTO new_id;
   UPDATE public.tour_questions SET is_active=false WHERE tour_id=oldq.tour_id AND question_id=oldq.id AND is_active;
   GET DIAGNOSTICS cnt=ROW_COUNT;
   IF cnt<>1 THEN RAISE EXCEPTION 'T2_old_link_count: %',reftext; END IF;
   INSERT INTO public.tour_questions(tour_id,question_id,order_no,is_active) VALUES(oldq.tour_id,new_id,oldq.order_no,true);
   INSERT INTO public.question_version_links(old_question_id,new_question_id,link_type,reason)
   VALUES(oldq.id,new_id,'replacement','Economics Gen2 season2 Tour2: actual high-order difficulty replacement; old question preserved');
   FOR i IN 0..3 LOOP
     INSERT INTO public.question_answer_diagnostics(question_id,answer_kind,answer_key,answer_value,is_correct,
        mistake_type,weak_skill,feedback_ru,feedback_uz,feedback_en,next_action_ru,next_action_uz,next_action_en,rule_json,quality_status)
     VALUES(new_id,'mcq_option',chr(65+i),NULL,i=idx,
        CASE WHEN i=idx THEN NULL ELSE 'multi_step_economic_reasoning' END,oldq.subtopic,
        'Выбрано: '||(x->'options_ru'->>i)||E'\n'||ruwhy||E'\nОтвет: '||(x->'options_ru'->>idx),
        'Tanlov: '||(x->'options_uz'->>i)||E'\n'||uzwhy||E'\nJavob: '||(x->'options_uz'->>idx),
        'Selected: '||(x->'options_en'->>i)||E'\n'||enwhy||E'\nCorrect: '||(x->'options_en'->>idx),
        CASE WHEN i=idx THEN NULL ELSE 'Перепроверьте каждый шаг.' END,
        CASE WHEN i=idx THEN NULL ELSE 'Har bir bosqichni tekshiring.' END,
        CASE WHEN i=idx THEN NULL ELSE 'Check each step.' END,
        jsonb_build_object('diagnostic_code','EC9708_G2_T2T'||substring(reftext from 'T-([0-9]{3})')||'_V2_'||chr(65+i)),
        'published');
   END LOOP;
 END LOOP;
 UPDATE public.questions q SET difficulty=
  CASE WHEN right(q.book_ref,3) IN ('002','003','004','006','009','017') THEN 'easy' ELSE 'medium' END
 WHERE q.subject_id=7 AND q.book_ref ~ '^EC9708:G2:EC9708-G2-T2-T-[0-9]{3}$'
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d) z WHERE z->>'ref'=q.book_ref);
 GET DIAGNOSTICS cnt=ROW_COUNT;
 IF cnt<>11 THEN RAISE EXCEPTION 'T2_unchanged_expected11: %',cnt; END IF;
 SELECT count(*),count(*) FILTER(WHERE q.difficulty='easy'),
 count(*) FILTER(WHERE q.difficulty='medium'),count(*) FILTER(WHERE q.difficulty='hard')
 INTO cnt,ez,med,hard
 FROM public.tours t JOIN public.tour_questions l ON l.tour_id=t.id AND l.is_active
 JOIN public.questions q ON q.id=l.question_id WHERE t.subject_id=7 AND t.season_id=2 AND t.tour_no=2;
 IF cnt<>20 OR ez<>6 OR med<>10 OR hard<>4 THEN
 RAISE EXCEPTION 'T2_mix_invalid: %,%,%,%',cnt,ez,med,hard; END IF;
END $tour1$;
COMMIT;
